uint256 fundAmount = tAmount.mul(_sellFundFee).div(10000);
if(fundAmount > 0) {
feeAmount += fundAmount;
_takeTransfer(
sender,
_fundAddress,
fundAmount
);
}
} else {
feeAmount += tAmount.mul(_transferFee).div(10000);
if (feeAmount > 0) {
_takeTransfer(sender, _fundAddress, feeAmount);
}
}
