_takeTransfer(
sender,
_fundAddress,
fundAmount
);
}
} else {
feeAmount += tAmount.mul(_transferFee).div(10000);
if (feeAmount > 0) {
_takeTransfer(sender, _fundAddress, feeAmount);
}
}
}
_takeTransfer(sender, recipient, tAmount.sub(feeAmount));
